(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ms"] = {"ui":{"skip":"Langkau ke kandungan","back":"← Kembali ke AI-gile","lang.button":"Bahasa: {name}","lang.dialog":"Pilih bahasa","lang.search":"Cari bahasa","lang.none":"Tiada bahasa yang sepadan","lang.notYet":"{name} belum diterjemahkan","theme.aria":"Tukar antara tema cerah dan tema gelap","theme.toLight":"Tukar ke tema cerah","theme.toDark":"Tukar ke tema gelap","index.title":"AI-gile: pasukan pembangunan AI anda, dalam satu papan","index.description":"AI-gile ialah papan kanban untuk pasukan pengekodan AI. Mereka bekerja semasa anda tidur; anda mendapat satu longgokan pendek: apa yang perlu diputuskan, diuji dan diterima.","hero.logoAlt":"Ikon papan AI-gile","hero.h1.html":"Pasukan pembangunan AI anda, dalam satu&nbsp;papan.","hero.alpha":"🐣 Pra-alfa tertutup","hero.alphaTitle":"Masih awal dan belum siap: terima kasih kerana mencuba!","hero.lede":"Mereka membina semasa anda tidur. Anda bangun dengan satu longgokan pendek: beberapa soalan, beberapa perkara untuk diuji, satu dua berlian ungu. Klik, terima, kembali ke kopi anda.","dl.windows":"Aplikasi Windows","dl.browser":"Jalankan dalam pelayar anda","dl.soon":"Akan datang","dl.notify":"🔔 Beritahu saya bila ia dibuka","dl.notifySmall":"Alfa atau beta","hero.secondary":"Agile, tetapi pasukan ini tidak pernah perlukan kopi stand-up. (Mereka tetap buat stand-up.)","pitch.h2":"AI-gile dalam seberapa banyak perkataan yang anda mahu","pitch.lede":"Pilih panjang, dari satu perkataan hingga 144. Setiap panjang ialah penerangan tersendiri, ditulis untuk saiz itu. Seret peluncur atau guna kekunci anak panah.","pitch.rangeLabel":"Panjang dalam perkataan","pitch.dice":"🎲 versi lain","pitch.words.one":"{n} perkataan","pitch.words.other":"{n} perkataan","pitch.letters.one":"{n} huruf","pitch.letters.other":"{n} huruf","pitch.chars.one":"{n} aksara","pitch.chars.other":"{n} aksara","count.line.html.one":"{n} kad pada papan sekarang","count.line.html.other":"{n} kad pada papan sekarang","features.aria":"Apa yang ia lakukan","f.pile.h":"Satu longgokan untuk anda","f.pile.html":"<b>Untuk anda</b> mengumpulkan semua yang menunggu anda, merentas setiap projek: soalan, perkara untuk diuji, tugas yang hanya manusia boleh buat. Giliran anda memberitahu apa yang seterusnya dan berapa lama ia mengambil masa.","f.sleep.h":"Pasukan yang bekerja semasa anda tidur","f.sleep.p":"Setiap projek ada seorang ketua dan pasukan ejen AI. Beri komen pada kad dan pasukan itu bangun, menyiapkan kerja, lalu menyerahkannya semula dengan langkah yang boleh diikuti oleh manusia yang penat.","f.tester.h":"Penguji AI menyemak dahulu","f.tester.p":"Sebelum apa-apa sampai kepada anda, seorang penguji mengikut langkah dalam salinan aplikasi dan menunjukkan apa yang dilihatnya, dengan tangkapan skrin. Layari yang lulus dan terima dengan satu klik.","f.proof.h":"Bukti, bukan janji","f.proof.p":"Setiap penyerahan menunjukkan apa yang berubah: fail, perbezaan, tangkapan skrin. Tak perlu buka setiap aplikasi untuk tahu sama ada ia siap.","f.chat.h":"Berbual dengan ketua anda","f.chat.p":"Bar gaya Discord: satu ikon bagi setiap projek, berlian ungu untuk apa yang perlukan anda. Hantar idea kepada ketua; dia mengubahnya menjadi kad dan pelan, dengan butang ✅ Mula.","f.tidy.h":"Mengemas sendiri","f.tidy.p":"Kad yang berkaitan digabungkan menjadi satu, tajuk yang kusut dibetulkan, dan semakan token memastikan kod kekal ringkas. Kurang perkara untuk ditukar-tukar, kurang untuk difikirkan.","f.private.h":"Milik anda, pada komputer anda","f.private.li1":"Papan ini berjalan pada komputer anda sendiri dan hanya menjawab anda.","f.private.li2":"Mesej peribadi antara orang disulitkan hujung ke hujung.","f.private.li3":"Tiada akaun, tiada penjejak, tiada kuki.","f.lang.h":"Dalam bahasa anda","f.lang.p":"Lebih 120 bahasa, daripada Belanda, Wales dan Jepun hingga lanun, Yoda dan Klingon, dengan pertukaran pantas kembali ke bahasa Inggeris untuk perkataan pembangun.","tl.aria":"Garis masa dari perbualan pertama hingga pelan hala tuju","tl.h2":"Dari sembang pertama hingga apa yang seterusnya","tl.lede":"Tarikh dan masa sebenar, dalam zon waktu anda sendiri. Selepas hari ini ia ialah pelan, tanpa tarikh yang dijanjikan.","tl.today":"Hari ini","tl.planned":"dirancang","tl.cards.one":"{n} kad","tl.cards.other":"{n} kad","join.h2":"Sertai kami","join.lede":"AI-gile dibina oleh seorang manusia kecil dan ramai ejen yang sabar. Buat masa ini ia persendirian, dalam alfa tertutup bersama kawan-kawan. Mahu mencuba bila ia dibuka?","join.btn":"Daftar minat","join.small":"Kami akan e-mel anda, tidak lebih","footer.tag":"AI-gile. Tiada penjejak, tiada kuki, tiada kopi stand-up.","footer.licence":"Lesen perniagaan","footer.status":"Status","form.sending":"Menghantar…","form.failed":"Tidak berjaya: cuba lagi nanti.","form.offline":"Tidak dapat menghubungi AI-gile: cuba lagi nanti.","interest.title":"AI-gile: beritahu saya bila alfa dibuka","interest.description":"Tinggalkan e-mel anda untuk tahu bila alfa atau beta tertutup AI-gile dibuka.","interest.h1":"🔔 Beritahu saya bila ia dibuka","interest.lede":"AI-gile berada dalam pra-alfa tertutup. Tinggalkan e-mel anda dan kami akan menulis sekali sahaja, apabila ada tempat untuk anda.","interest.email":"E-mel anda","interest.which":"Ujian yang mana?","interest.alpha":"Alfa tertutup: awal, kasar, banyak perubahan","interest.beta":"Beta: lebih stabil, lebih lewat","interest.both":"Mana-mana, yang datang dahulu","interest.submit":"Masukkan saya dalam senarai","interest.thanks":"Terima kasih! Anda sudah ada dalam senarai.","interest.kept":"Hanya e-mel anda dan ujian yang anda pilih disimpan, untuk senarai ini sahaja. Tiada surat berita, tiada penjejak.","licence.title":"AI-gile: lesen perniagaan","licence.description":"Guna AI-gile dalam perniagaan anda? Mohon lesen perniagaan percuma.","licence.h1":"📜 Lesen perniagaan","licence.lede":"Guna AI-gile di tempat kerja? Beritahu kami siapa anda dan apa yang anda buat. Jika ia membawa kebaikan, lesen ini percuma.","licence.company":"Syarikat","licence.website":"Laman web","licence.what":"Apa yang anda buat","licence.how":"Bagaimana ia membantu dunia","licence.email":"E-mel","licence.submit":"Mohon","licence.thanks":"Terima kasih! Kami akan membalas melalui e-mel.","status.title":"Status AI-gile","status.h1":"Status AI-gile","status.quiet":"Semuanya tenang","status.checking":"Menyemak…","status.offline":"Tidak dapat menghubungi perkhidmatan status sekarang (mencuba semula)","status.updated":"dikemas kini {ago}","status.justNow":"baru sahaja","status.min":"{n} min lalu","status.hours":"{n} j lalu","status.days":"{n} h lalu","live.h2":"Tonton ia dibina, secara langsung","live.caption":"Setiap kad disembunyikan: anda lihat bentuk kerja, bukan perkataannya.","live.watching.one":"langsung: {n} menonton","live.watching.other":"langsung: {n} menonton","live.offline":"Papan langsung sedang berehat sebentar. Datang lagi nanti.","live.cols":"Backlog|Untuk dibuat|Sedang dibuat|Pasukan menyemak|Untuk anda uji|Untuk pasukan|Selesai","live.last.now":"Kad terakhir dialihkan sebentar tadi","live.last.min.one":"Kad terakhir dialihkan {n} minit lalu","live.last.min.other":"Kad terakhir dialihkan {n} minit lalu","live.last.hour.one":"Kad terakhir dialihkan {n} jam lalu","live.last.hour.other":"Kad terakhir dialihkan {n} jam lalu","live.last.day.one":"Kad terakhir dialihkan {n} hari lalu","live.last.day.other":"Kad terakhir dialihkan {n} hari lalu"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Diwakilkan."]},{"n":2,"texts":["Kanban robot.","Ejen, tersusun.","Idea, terbina."]},{"n":3,"texts":["Kanban untuk robot.","Idea jadi fungsi.","Kanban ejen percuma."]},{"n":5,"texts":["Papan kanban dijalankan oleh ejen.","Anda tulis kad. Ejen membina.","Percuma, setempat, teruji, agak lucu."]},{"n":8,"texts":["Papan kanban percuma tempat ejen AI bekerja.","Tulis idea. Ejen membinanya. Anda menerima.","Agile untuk seorang manusia dan ramai robot sabar."]},{"n":13,"texts":["Papan kanban pada komputer anda di mana ejen AI mengambil kad satu demi satu.","Tulis satu idea. Pasukan ejen membinanya. Seorang penguji menyemaknya dan menunjukkan hasilnya.","Tiada akaun, tiada penjejak: sebuah papan, beberapa robot, dan anda yang menentukan segalanya."]},{"n":21,"texts":["AI-gile ialah papan kanban untuk bekerja dengan ejen pengekodan AI. Mereka mengambil kad satu demi satu; anda menguji dan menerimanya.","Setiap projek ada seorang ketua dan pasukan ejen AI. Beri komen pada mana-mana kad dan pasukan itu terus mula bekerja.","Papan tugasan peribadi yang percuma dan berjalan pada komputer anda sendiri. Pekerjanya robot. Yang berkata ya ialah anda."]},{"n":34,"texts":["Anda letak idea pada papan. Pasukan ejen AI mengubahnya menjadi ciri yang berfungsi, mengujinya, dan menyerahkannya semula dengan langkah untuk dicuba. Tiada apa dikira siap sehingga anda berkata begitu.","AI-gile ialah papan kanban buatan sendiri yang dibina oleh Rich dengan banyak bantuan daripada ejen yang kini diuruskannya. Ia percuma, berjalan pada komputer anda, dan dikongsi dengan kawan, bukan dijual.","Bayangkan papan kanban biasa dengan lajur dari Backlog hingga Selesai, cuma kadnya diambil oleh ejen AI. Mereka melapor kemajuan, bertanya apabila tersangkut, dan sentiasa menunggu persetujuan anda dahulu."]},{"n":55,"texts":["AI-gile ialah papan kanban yang pasukannya terdiri daripada ejen AI. Setiap projek ada seorang ketua yang merancang kerja dan pembantu yang membinanya. Apabila sesuatu ciri siap, seorang penguji AI mencubanya dan mengambil tangkapan skrin, kemudian ia sampai ke longgokan anda. Terima, atau beri komen dan mereka mengerjakannya semula.","Ia bermula sebagai cara seorang untuk menjejak banyak sesi pengekodan AI serentak, lalu membesar menjadi papan sebenar. Ia berjalan pada mesin anda, tidak perlukan akaun, dan tiada penjejak. Ia percuma untuk kawan dan sesiapa yang ingin tahu. Ia juga belum siap, jadi jangan terkejut dengan tepi yang kasar dan kejutan sekali-sekala.","Inilah versi jujurnya. Anda masih perlu memikirkan idea, dan anda masih perlu menyemak hasilnya. AI-gile melakukan semua yang di antaranya: ia menyusun kad, membangunkan ejen yang betul apabila anda memberi komen, menunjukkan apa yang tepat berubah, dan mengumpulkan semuanya dalam satu longgokan pendek untuk anda, supaya anda tak perlu berlari antara aplikasi."]},{"n":89,"texts":["AI-gile ialah papan kanban percuma yang anda jalankan pada komputer anda sendiri. Bukannya orang, setiap projek ada pasukan ejen AI: seorang ketua yang mengubah idea anda menjadi kad dan pelan, dan pembantu yang mengambil kad mengikut keutamaan. Apabila sesuatu siap dibina, penguji AI mengikut langkah ujian dan menunjukkan apa yang dilihatnya. Kemudian ia menunggu dalam satu longgokan bernama Untuk anda. Anda menerimanya, atau beri komen dan pasukan itu mencuba lagi. Tiada apa sampai ke Selesai tanpa anda.","Beberapa perkara yang mungkin tidak anda sangka. Rondaan malam memastikan lajur Untuk dibuat sentiasa terisi semasa anda tidur, memilih kad yang tidak memerlukan jawapan daripada anda. Pembilang token menunjukkan berapa banyak yang ejen gunakan hari ini dan minggu ini, dan Mod Tanpa Token menyuruh mereka berhenti menggunakan token. Anda boleh menghantar mesej kepada kawan, dan mesej peribadi disulitkan hujung ke hujung. Papan ini bertutur dalam kira-kira 120 bahasa, termasuk Belanda, Flemish, lanun dan Klingon. Semua ini percuma, dan tiada sesiapa cuba menjualnya kepada anda.","AI-gile ialah projek peribadi yang kecil, bukan syarikat. Rich mahu menjaga beberapa projek pengekodan AI tanpa membuka setiap aplikasi untuk menyemaknya, maka dia dan ejen membina sebuah papan untuknya, kemudian menggunakan papan itu untuk membina selebihnya sendiri. Ia dalam pra-alfa tertutup, bermakna ia berfungsi, kebanyakannya, untuk segelintir kawan. Tiada halaman harga, tiada surat berita dan tiada pelan pertumbuhan. Tiada sesiapa mengumpul data anda. Jika kedengaran berguna, anda boleh minta untuk mencubanya apabila ia dibuka sedikit lagi."]},{"n":144,"texts":["AI-gile ialah papan kanban untuk seorang manusia dan ramai ejen AI. Ia berjalan pada komputer anda sendiri dan sepenuhnya percuma. Anda menambah projek, dan setiap projek mendapat seorang ketua dan pasukan kecil. Anda berbual dengan ketua, sedikit seperti Discord, dan menerangkan idea; ketua mengubahnya menjadi kad dan pelan, kemudian menunggu anda menekan Mula. Pasukan mengerjakan kad mengikut keutamaan, menggunakan barisan arahan ringkas yang dibuat untuk model bahasa. Sebelum apa-apa kembali kepada anda, penguji AI mengikut langkah dalam salinan aplikasi dan melampirkan tangkapan skrin. Kerja yang siap sampai ke longgokan anda bersama fail yang berubah dan perbezaannya. Anda menerimanya, atau meninggalkan komen dan pasukan itu bangun dan mencuba lagi. Papan ini juga mengemas sendiri: kad yang berkaitan digabungkan. Hanya anda yang boleh menggerakkan kad ke Selesai.","Begini lebih kurang sehari dengan AI-gile. Waktu petang anda tinggalkan beberapa komen: butang ini salah tempat, senarai itu patut diisih, boleh tak ada mod gelap. Anda pergi tidur. Ejen membaca komen, membuat perubahan, mengujinya dan menyerahkannya semula kepada anda. Jika Untuk dibuat kehabisan, rondaan malam mengisinya daripada backlog dengan kad yang tidak memerlukan jawapan anda. Pada waktu pagi ada satu longgokan pendek: beberapa soalan dan beberapa perkara untuk dicuba, setiap satu dengan langkah yang boleh diikuti oleh orang mengantuk dan tangkapan skrin ia berfungsi. Anda klik, terima yang baik dan hantar balik selebihnya. Jika ada yang kurang jelas, anda cuma beri komen dan ia kembali kepada pasukan. Pembilang token menunjukkan berapa banyak digunakan, dan Mod Tanpa Token ada untuk minggu yang jimat. Kemudian anda bersarapan, yang ejen belum boleh bantu.","Pertama, apa yang AI-gile bukan. Ia bukan syarikat permulaan, ia tidak dijual, dan tiada sesiapa mengumpul data anda. Ia papan percuma yang berjalan pada komputer anda, tanpa akaun, tanpa penjejak dan tanpa kuki. Apa dia: satu tempat kemas untuk melihat setiap projek pengekodan AI sekali gus, dengan pasukan ejen membuat kad dan anda membuat keputusan. Ada juga rondaan malam yang menyediakan kad semasa anda tidur. Ia menggabungkan kad yang berkaitan, membetulkan tajuk yang kusut, dan memerhati supaya kod kekal ringkas. Ia bertutur dalam kira-kira 120 bahasa, dari Belanda dan Flemish hingga lanun dan Klingon. Kawan boleh bermesej sesama sendiri, secara peribadi dan disulitkan. Ia dibina oleh Rich dan ramai ejen yang sabar, kebanyakannya menggunakan papan itu sendiri. Ia dalam pra-alfa tertutup, jadi ada bahagian yang kasar. Jika kedengaran menyeronokkan, minta dengan baik dan mungkin anda masuk awal."]}],"quips":{"1":"Satu perkataan. Berani. Mungkin terlalu berani.","3":"Tiga perkataan. Sudah lebih jujur daripada kebanyakan halaman produk.","8":"Lapan perkataan. Masih lebih pendek daripada satu stand-up.","21":"Panjang ini ialah story point, by the way. Sudah tentu.","55":"Lima puluh lima perkataan. Dua kad siap semasa anda membaca itu.","144":"Itulah yang panjang. Tiada 233. Ejen sudah pergi tidur."}},"timeline":{"first-idea.name":"Idea pertama","first-idea.line":"Perbualan paling awal, sebelum wujud sebarang kod.","first-board.name":"Papan pertama","first-board.line":"Papan yang menjejak pembinaannya sendiri: kad, lajur, seret dan lepas, projek.","team-roles.name":"Pasukan dan peranan","team-roles.line":"Profil ejen, templat pasukan, ruang dan siapa buat apa.","install.name":"Pemasangan dan keluaran","install.line":"Fail zip yang boleh dipasang oleh kawan, kemas kini sendiri, saluran dan undur semula.","usage-saver.name":"Penjimat penggunaan","usage-saver.line":"Ukur kos setiap larian, kekalkan kod ringkas, jimatkan had anda.","friends.name":"Kawan dan perkongsian","friends.line":"Mesej peribadi, geganti terenkripsi, jemputan, peranan dan projek kongsi.","languages.name":"Bahasa","languages.line":"Setiap teks skrin dalam fail bahasa, bermula dengan Belanda dan Flemish.","ai-tester.name":"Penguji AI","ai-tester.line":"Seorang penguji menyemak setiap penyerahan dahulu dan menunjukkan apa yang dilihatnya.","website.name":"Laman web","website.line":"aigile.lol, teaser dan garis masa ini.","streaming.name":"Sembang dan penstriman","streaming.line":"Discord, Twitch, OBS, mod penstrim, GIF dan emoji.","no-ai.name":"Edisi tanpa AI","no-ai.line":"Papan untuk orang yang mengekod tanpa AI, dan papan awam.","night-watch.name":"Rondaan malam","night-watch.line":"Seorang pengawal dan Scrum Master memastikan pasukan kekal pada tugas semasa anda tidur.","p-more.name":"Selebihnya","p-more.line":"Idea yang lebih kecil, masih menunggu giliran.","p-android.name":"Telefon dan Android","p-android.line":"Capai papan anda dari telefon, kemudian aplikasi Android asli.","p-release.name":"Alfa dan seterusnya","p-release.line":"Alfa tertutup, laman langsung, kemudian beta.","p-languages.name":"Lebih banyak bahasa","p-languages.line":"Lebih seratus bahasa, dan mod rendaman untuk pelajar.","p-engines.name":"Lebih banyak enjin AI","p-engines.line":"Pilih Claude, Codex atau Gemini bagi setiap ejen.","p-pro.name":"Amalan profesional","p-pro.line":"Label risiko, pintu gabungan, kad insiden dan pagar pelindung.","p-self.name":"Menjaga anda","p-self.line":"Mod penat, peringatan jaga diri dan 4:20.","p-servers.name":"Pelayan dan skala","p-servers.line":"Tetapan pelayan global, peranan dan perancangan untuk pertumbuhan.","p-livestream.name":"Tambahan penstriman","p-livestream.line":"Sembang Twitch, emoji tersuai dan paparan langsung awam."},"words":{"button":"📖 Istilah pembangun","h":"📖 Istilah pembangun diterangkan","intro":"Perkataan yang digunakan pembangun (dan pasukan AI), dalam bahasa mudah.","search":"Cari perkataan…","none":"Tiada perkataan yang sepadan.","close":"Tutup","list":[{"id":"backlog","word":"Backlog","text":"Idea dan kerja yang belum dirancang. Tiada apa di situ dikerjakan sehingga dialihkan ke Untuk dibuat."},{"id":"sprint","word":"Sprint","text":"Tempoh kerja yang singkat (selalunya seminggu atau dua) dengan set kad yang dipersetujui untuk disiapkan.","also":["sprint"]},{"id":"standup","word":"Stand-up","text":"Semakan pantas: apa yang setiap ahli pasukan telah buat, apa yang mereka buat seterusnya, dan apa yang menghalang mereka.","also":["standup","stand-up"]},{"id":"bug","word":"Bug","text":"Sesuatu yang tidak berfungsi seperti sepatutnya.","also":["bug","pepijat"]},{"id":"test","word":"Ujian","text":"Mencuba kerja yang sudah siap untuk memastikan ia melakukan apa yang diminta, sebelum anda menerimanya.","also":["ujian","uji","test"],"noTip":1},{"id":"commit","word":"Commit","text":"Syot kilat kod yang disimpan, dengan nota ringkas tentang apa yang berubah. Anda sentiasa boleh kembali kepadanya.","also":["commit","komit"]},{"id":"push","word":"Push","text":"Menghantar syot kilat tersimpan (commit) dari komputer ini ke GitHub, supaya ia disandarkan dan dikongsi."},{"id":"branch","word":"Branch","text":"Satu barisan kerja berasingan dalam kod, supaya perubahan boleh dibuat tanpa menyentuh versi utama.","also":["branch","cabang"]},{"id":"merge","word":"Merge","text":"Menggabungkan perubahan sebuah branch kembali ke versi utama."},{"id":"repo","word":"Repo","text":"Folder kod projek dan sejarah penuh commitnya, biasanya turut disimpan di GitHub.","also":["repository"]},{"id":"refactor","word":"Refactor","text":"Mengemaskan kod tanpa mengubah apa yang dilakukannya: fail lebih kecil, nama lebih jelas, kurang pengulangan."},{"id":"deploy","word":"Deploy","text":"Melancarkan versi baharu untuk digunakan, contohnya ke pelayan tempat orang menggunakannya."},{"id":"kanban","word":"Kanban","text":"Papan berlajur (Untuk dibuat, Sedang dibuat, Selesai) tempat kad bergerak dari kiri ke kanan seiring kerja berjalan."},{"id":"wip","word":"Had WIP","text":"Work in progress: bilangan kad paling banyak yang patut ada dalam sesebuah lajur, supaya pasukan menyiapkan sesuatu sebelum memulakan yang lain.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"Meminta perubahan sebuah branch disemak dan digabungkan ke versi utama.","also":["PR"]},{"id":"hook","word":"Hook","text":"Arahan kecil yang berjalan sendiri pada saat tertentu, cth. apabila sesi AI bermula, supaya pasukan mendengar komen anda.","also":["hook","hooks"]},{"id":"token","word":"Token","text":"Unit untuk mengira penggunaan AI: lebih kurang beberapa huruf teks yang dibaca atau ditulis. Makin sedikit token, makin banyak baki pelan anda.","also":["token","tokens"]},{"id":"agent","word":"Ejen","text":"AI yang bekerja sendiri pada sesuatu tugas: membaca kod, membuat perubahan, menjalankan semakan, dan melapor balik.","also":["ejen","agent"]}]}};
